// ===== KONFIGURATION =====================================================
// Standard-Absender, wenn der Aufrufer keinen mitschickt
const STANDARD = { email: 'torsten.laub@tc-oberthal.de', name: 'Tennisclub Oberthal e.V.' };
// Absender mit eigenem SMTP-Konto (Knoten), über das sie versenden:
//   'primaer' → Knoten „E-Mail senden (SMTP)“ (torsten.laub@…)
//   'zweit'   → Knoten „E-Mail senden (SMTP Benjamin)“ (benjamin.hartyniuk@…)
// Andere Absender (z. B. persönliche Adresse ohne SMTP-Konto) → Ersatz/Standard, Antworten gehen an sie.
const KONTEN = {
  'torsten.laub@tc-oberthal.de': 'primaer',
  'benjamin.hartyniuk@tc-oberthal.de': 'zweit',
};
// ========================================================================

const b = $input.first().json.body || {};
const fehler = [];

// ---- Adressen ----------------------------------------------------------
// an/cc/bcc: Text (mit Komma/Semikolon getrennt) oder Liste
function liste(v) {
  const arr = Array.isArray(v) ? v : String(v || '').split(/[;,]/);
  return arr.map((x) => String(x || '').trim()).filter(Boolean);
}
const MAIL = /^[^@\s<>"]+@[^@\s<>"]+\.[^@\s<>"]+$/;
function nurAdresse(x) { const m = /<([^>]+)>/.exec(x); return (m ? m[1] : x).trim(); }
function pruefeListe(feld, arr) {
  for (const x of arr) if (!MAIL.test(nurAdresse(x))) fehler.push('Ungültige Adresse in ' + feld + ': ' + x);
  return arr.join(', ');
}
const an = pruefeListe('an', liste(b.an));
const cc = pruefeListe('cc', liste(b.cc));
const bcc = pruefeListe('bcc', liste(b.bcc));
let antwortAn = pruefeListe('antwort_an', liste(b.antwort_an));

// Absender, in dieser Reihenfolge:
//  1. absender      – wer im Portal auf „Senden“ drückt (oder ein fest gewählter Absender)
//  2. absender_ersatz – Ersatz je Anwendung aus den Portal-Stammdaten
//  3. STANDARD
// Genommen wird die erste Adresse, für die es in KONTEN ein SMTP-Konto gibt. Wird nicht der gewünschte Absender genommen,
// gehen Antworten an ihn (Reply-To), sofern keine Antwortadresse vorgegeben ist und er nicht selbst Empfänger ist.
const sauber = (x) => String(x || '').replace(/["<>\r\n]/g, '').trim();
const kandidaten = [
  { email: b.absender, name: b.absender_name },
  { email: b.absender_ersatz, name: b.absender_ersatz_name },
  STANDARD,
].map((k) => ({ email: String(k.email || '').trim().toLowerCase(), name: sauber(k.name) })).filter((k) => k.email);
const gewaehlt = kandidaten.find((k) => KONTEN[k.email]) || { email: STANDARD.email.toLowerCase(), name: STANDARD.name };
const absEmail = gewaehlt.email;
const absName = gewaehlt.name || (absEmail === STANDARD.email.toLowerCase() ? STANDARD.name : '');
const konto = KONTEN[absEmail] || 'primaer';
const gewuenscht = kandidaten[0] && kandidaten[0].email !== absEmail && MAIL.test(kandidaten[0].email) ? kandidaten[0].email : '';
const hinweis = gewuenscht ? 'Kein SMTP-Konto für ' + gewuenscht + ' – gesendet als ' + absEmail : '';
const ABSENDER = absName ? absName + ' <' + absEmail + '>' : absEmail;
if (gewuenscht && !antwortAn && !liste(b.an).map((x) => nurAdresse(x).toLowerCase()).includes(gewuenscht)) {
  antwortAn = kandidaten[0].name ? kandidaten[0].name + ' <' + gewuenscht + '>' : gewuenscht;
}

const modus = (b.modus || 'senden').toLowerCase();
if (modus !== 'senden' && modus !== 'entwurf') fehler.push('Unbekannter Modus: ' + modus);
if (!an) fehler.push('Kein Empfänger angegeben');
if (!b.betreff) fehler.push('Kein Betreff angegeben');

const anhaenge = Array.isArray(b.anhaenge) ? b.anhaenge : [];
const binary = {};
const felder = [];
const anhInfo = [];

for (let i = 0; i < anhaenge.length; i++) {
  const a = anhaenge[i] || {};
  const name = a.dateiname || ('anhang_' + (i + 1) + '.pdf');
  const data = String(a.inhalt_base64 || '').replace(/\s+/g, '');
  if (!data) {
    fehler.push('Anhang ' + name + ' ist leer');
    continue;
  }
  const key = 'anhang_' + i;
  binary[key] = {
    data: data,
    mimeType: a.mime || 'application/pdf',
    fileName: name,
  };
  felder.push(key);
  anhInfo.push({
    dateiname: name,
    mime: a.mime || 'application/pdf',
    objekt: a.objekt || '',
    paperless_root_id: a.paperless_root_id || null,
    paperless_version_id: a.paperless_version_id || null,
    data: data,
  });
}

// ---- RFC822-Nachricht fuer Entwurf (IMAP) ------------------------------
function b64utf8(s) {
  return Buffer.from(String(s || ''), 'utf8').toString('base64');
}
function encHeader(s) {
  // nur kodieren, wenn Nicht-ASCII enthalten ist
  return /^[\x20-\x7e]*$/.test(s) ? s : '=?UTF-8?B?' + b64utf8(s) + '?=';
}
function wrap76(s) {
  return (s.match(/.{1,76}/g) || []).join('\r\n');
}
function encFileName(n) {
  return /^[\x20-\x7e]*$/.test(n) ? '"' + n.replace(/"/g, '') + '"' : '"' + encHeader(n) + '"';
}

const isHtml = (b.text_format || 'text').toLowerCase() === 'html';
const domain = absEmail.split('@')[1] || 'tc-oberthal.de';
const rnd = Date.now().toString(36) + '.' + Math.random().toString(36).slice(2, 10);
const messageId = '<sap.' + rnd + '@' + domain + '>';
const boundary = '----=_TCO_' + rnd;

const kopf = [
  'From: ' + (absName ? encHeader(absName) + ' <' + absEmail + '>' : absEmail),
  'To: ' + an,
];
if (cc) kopf.push('Cc: ' + cc);
if (bcc) kopf.push('Bcc: ' + bcc);
if (antwortAn) kopf.push('Reply-To: ' + antwortAn);
kopf.push(
  'Subject: ' + encHeader(b.betreff || ''),
  'Date: ' + new Date().toUTCString().replace('GMT', '+0000'),
  'Message-ID: ' + messageId,
  'MIME-Version: 1.0',
  'X-TCO-Source: ' + (b.quelle || 'Portal-Mailversand'),
  'X-TCO-Objekt: ' + (b.anwendung || '') + ' ' + (b.objekt || ''),
  'Content-Type: multipart/mixed; boundary="' + boundary + '"'
);

const teile = [];
teile.push(
  '--' + boundary + '\r\n' +
  'Content-Type: ' + (isHtml ? 'text/html' : 'text/plain') + '; charset=UTF-8\r\n' +
  'Content-Transfer-Encoding: base64\r\n\r\n' +
  wrap76(b64utf8(b.text || '')) + '\r\n'
);
for (const a of anhInfo) {
  teile.push(
    '--' + boundary + '\r\n' +
    'Content-Type: ' + a.mime + '; name=' + encFileName(a.dateiname) + '\r\n' +
    'Content-Disposition: attachment; filename=' + encFileName(a.dateiname) + '\r\n' +
    'Content-Transfer-Encoding: base64\r\n\r\n' +
    wrap76(a.data) + '\r\n'
  );
}
const rfc822 = kopf.join('\r\n') + '\r\n\r\n' + teile.join('') + '--' + boundary + '--\r\n';

return [{
  json: {
    ok: fehler.length === 0,
    fehler: fehler.join('; '),
    modus: modus,
    von: ABSENDER,
    konto: konto,
    hinweis: hinweis,
    an: an,
    cc: cc,
    bcc: bcc,
    antwort_an: antwortAn,
    betreff: b.betreff || '',
    text: isHtml ? '' : (b.text || ''),
    html: isHtml ? (b.text || '') : '',
    format: isHtml ? 'html' : 'text',
    anwendung: b.anwendung || '',
    objekt: b.objekt || '',
    benutzer: b.benutzer || '',
    anhangFelder: felder.join(','),
    anhaenge: anhInfo.map(a => ({
      dateiname: a.dateiname,
      objekt: a.objekt,
      paperless_root_id: a.paperless_root_id,
      paperless_version_id: a.paperless_version_id,
    })),
    message_id_entwurf: messageId,
    rfc822: fehler.length === 0 ? rfc822 : '',
  },
  binary: binary,
}];
